return function(Mock,Library,test)
 local player=game:GetService('Players').LocalPlayer
 local oldHTTP,oldLoad,oldGeometry=game.HttpGet,loadstring,Mock.Geometry
 local function fixture(options)
  Mock.StrictIconLifecycle=true;Mock.ParentLockErrors=0;Mock.DestroyedIconWrites=0;Mock.Warnings={};player.LocaleId='pt-br'
  options=options or {};options.Id=options.Id or 'development-test';options.Settings=false;options.FileStorage=false;options.ReducedMotion=true
  local w=Library:CreateWindow(options);return w,w:CreateTab('Development'):CreateSection('Controls')
 end
 local function finish(w)
  w:Destroy();Mock.pump(100)
  assert(Mock.Connections==0,'Connections leaked: '..Mock.Connections)
  assert(Mock.ParentLockErrors==0 and Mock.DestroyedIconWrites==0,'Destroyed icon was modified')
  assert(#Mock.Warnings==0,table.concat(Mock.Warnings,'\n'))
  game.HttpGet,loadstring=oldHTTP,oldLoad;player.LocaleId='pt-br';Mock.Geometry=oldGeometry;Mock.YieldingTasks=false;Mock.DeferDestroying=false;Mock.StrictIconLifecycle=false
 end
 local messages={count={Source='Coletados: {count}',Values={['en-US']='Collected: {count}'}},title={Source='Configuração',Values={['en-US']='Settings'}}}
 test('auto locale follows the Roblox account and uses English for unsupported languages',function()
  local w=fixture();assert(w:GetLocale()=='pt-BR');player.LocaleId='en-gb';w:SetLocale('auto');assert(w:GetLocale()=='en-US');player.LocaleId='ja-jp';w:SetLocale('auto');assert(w:GetLocale()=='en-US');finish(w)
 end)
 test('manual language survives profiles and old profiles keep the current preference',function()
  local w=fixture();w:SetLocale('en-US');local p=w:ExportConfig(true);w:SetLocale('pt-BR');assert(w:ImportConfig(p) and w:GetLocale()=='en-US');p.Appearance.Locale=nil;assert(w:ImportConfig(p) and w:GetLocale()=='en-US');finish(w)
 end)
 test('dictionary text and parameter bindings update without changing flags',function()
  local w,s=fixture({Translations=messages});local label=s:AddLabel({Id='text',Title='Configuração'});local t=s:AddToggle({Id='active',Title='Configuração',Default=true})
  w:BindText(label.TitleLabel,'Text','count',{count=17});w:SetLocale('en-US');assert(label.TitleLabel.Text=='Collected: 17' and t.TitleLabel.Text=='Settings' and t:GetValue()==true and t.Title=='Configuração');w:SetLocale('pt-BR');assert(label.TitleLabel.Text=='Coletados: 17');finish(w)
 end)
 test('localization translates placeholders while preserving typed text and opt-out captions',function()
  local w,s=fixture({Translations=messages});local c=s:AddInput({Title='Configuração',Placeholder='Configuração',Default='Configuração'});local raw=s:AddLabel({Title='Configuração',Translate=false});w:SetLocale('en-US')
  assert(c.Input.Text=='Configuração' and c.Input.PlaceholderText=='Settings' and raw.TitleLabel.Text=='Configuração');finish(w)
 end)
 test('translation dictionaries validate atomically and preserve placeholders',function()
  local w=fixture({Translations=messages});assert(not pcall(w.RegisterTranslations,w,{broken={Source='{count}',Values={['en-US']='missing parameter'}}}));w:SetLocale('en-US');assert(w:Translate('count',{count=3})=='Collected: 3');assert(not pcall(Library.CreateWindow,Library,{Id='invalid-language',SourceLocale='auto'}));finish(w)
 end)
 test('new dictionaries can register an additional supported locale',function()
  local w=fixture();w:RegisterTranslations({greeting={Source='Olá',Values={['es-ES']='Hola'}}});w:SetLocale('es-ES');assert(w:GetLocale()=='es-ES' and w:Translate('greeting')=='Hola');finish(w)
 end)
 test('translation provider runs only on request and caches registered messages',function()
  local count=0;local w=fixture({TranslationProvider=function(request,ctx)count=count+1;assert(request.Text=='Olá {name}');ctx:ThrowIfCancelled();return 'Hello {name}'end})
  w:RegisterTranslations({greeting={Source='Olá {name}',Values={}}});w:SetLocale('en-US');assert(w:Translate('greeting',{name='G'})=='Olá G' and count==0 and #w:GetMissingTranslations()==1)
  local h=assert(w:RequestTranslation('greeting'));Mock.pump();assert(h:GetStatus().Status=='Completed' and count==1 and w:Translate('greeting',{name='G'})=='Hello G' and #w:GetMissingTranslations()==0);assert(not w:RequestTranslation('greeting'));finish(w)
 end)
 test('invalid provider output is reported and keeps the original message',function()
  local w=fixture({TranslationProvider=function()return 'bad translation'end});w:RegisterTranslations({greeting={Source='Olá {name}',Values={}}});w:SetLocale('en-US');local h=assert(w:RequestTranslation('greeting'));Mock.pump();assert(h:GetStatus().Status=='Failed' and #Mock.Warnings==1 and w:Translate('greeting',{name='G'})=='Olá G');Mock.Warnings={};finish(w)
 end)
 test('localized text cleanup survives deferred external parent destruction',function()
  local w,s=fixture({Translations=messages});s:AddLabel({Title='Configuração'});Mock.DeferDestroying=true;w.Gui:Destroy();Mock.pump(100);finish(w)
 end)
 test('internal translation pairs belong to one window and do not rewrite another project',function()
  local w=fixture();w:_t17('Atual','Current');local other=Library:CreateWindow({Id='other-language',Settings=false,FileStorage=false});local label=other:CreateTab('Data'):CreateSection('Data'):AddLabel({Title='Current'});assert(label.TitleLabel.Text=='Current');other:Destroy();finish(w)
 end)
 test('provider skips the source locale and discards a stale translated entry',function()
  local count=0;local w=fixture({TranslationProvider=function()count=count+1;task.wait(.2);return 'Hello'end});w:RegisterTranslations({greeting={Source='Olá',Values={}}});assert(not w:RequestTranslation('greeting') and count==0)
  Mock.YieldingTasks=true;w:SetLocale('en-US');local h=assert(w:RequestTranslation('greeting'));Mock.pump();w:RegisterTranslations({greeting={Source='Bom dia',Values={}}});Mock.pump(.3);assert(h:GetStatus().Status=='Completed' and w:Translate('greeting')=='Bom dia');finish(w)
 end)
 local function form(s,options)
  options=options or {};options.Id=options.Id or 'settings';options.Title='Settings';options.Fields={{Id='name',Type='Input',Title='Name',Default='Original',Required=true},{Id='amount',Type='Slider',Title='Amount',Min=0,Max=10,Default=2},{Id='enabled',Type='Toggle',Title='Enabled',Default=false}}
  return s:CreateForm(options)
 end
 test('form drafts do not commit values or dispatch callbacks',function()
  local w,s=fixture();local count=0;local f=form(s,{OnApply=function()count=count+1 end});f:SetDraft({name='Draft',enabled=true});Mock.pump();assert(f:IsDirty() and f:GetValue().name=='Original' and count==0);assert(f:Apply());Mock.pump();assert(count==1 and f:GetValue().name=='Draft' and not f:IsDirty());finish(w)
 end)
 test('forms apply pending text before FocusLost and cancel restores the committed draft',function()
  local w,s=fixture();local f=form(s);f.Fields.name.Input.Text='Pending';assert(f:IsDirty() and f:GetValue().name=='Original');assert(f:Apply() and f:GetValue().name=='Pending');f:SetDraft({name='Discard'});f:Cancel();assert(f:GetDraft().name=='Pending' and not f:IsDirty());finish(w)
 end)
 test('required and cross-field validation reject the entire form atomically',function()
  local w,s=fixture();local f=form(s,{Validate=function(v)return v.amount<8,{amount='Use a smaller amount'}end});f:SetDraft({name='',amount=9,enabled=true});assert(not f:Apply() and f:GetValue().amount==2 and not f:GetValue().enabled and f.Errors.name.Frame.Visible);f:SetDraft({name='Valid'});assert(not f:Apply() and f.Errors.amount.Frame.Visible);f:SetDraft({amount=5});assert(f:Apply() and f:GetValue().enabled);finish(w)
 end)
 test('profiles contain committed form values and omit draft controls',function()
  local w,s=fixture();local f=form(s);f:SetDraft({name='Committed'});f:Apply();f:SetDraft({name='Draft'});local p=w:ExportConfig(true);assert(p.Forms.settings.name=='Committed' and p.Flags['settings/name']==nil);f:SetDraft({name='Another'});f:Apply();assert(w:ImportConfig(p) and f:GetDraft().name=='Committed' and not f:IsDirty());finish(w)
 end)
 test('invalid form profile leaves unrelated flags and committed values unchanged',function()
  local w,s=fixture();local f=form(s);local t=s:AddToggle({Id='toggle',Default=false});local p=w:ExportConfig(true);p.Forms.settings.name='';p.Flags.toggle.Value=true;assert(not w:ImportConfig(p) and not t:GetValue() and f:GetValue().name=='Original');finish(w)
 end)
 test('form destruction is idempotent and releases its child listeners',function()
  local w,s=fixture();local f=form(s);f:Destroy();f:Destroy();assert(w._forms.settings==nil and w.Controls['settings/name']==nil);finish(w)
 end)
 test('reserved form field IDs fail without allocating group resources',function()
  local w,s=fixture();assert(not pcall(s.CreateForm,s,{Id='reserved',Fields={{Id='_apply',Type='Input'}}}));assert(not w._componentGroups or not w._componentGroups.reserved);finish(w)
 end)
 test('empty reusable groups reject duplicate instance IDs and release the namespace',function()
  local w,s=fixture();Library:RegisterComponent('empty',function()end,{Replace=true});local a=s:AddComponent('empty',{Id='instance'});assert(not pcall(s.AddComponent,s,'empty',{Id='instance'}));a:Destroy();assert(s:AddComponent('empty',{Id='instance'}));finish(w)
 end)
 test('reusable instances namespace their children and own independent resources',function()
  local w,s=fixture();Library:RegisterComponent('test-pair',function(ctx,props)local state=ctx:CreateState(1);ctx:Add('Slider',{Id='value',Title='Value',Min=0,Max=10,Default=props.Default or 2});ctx:Add('Toggle',{Id='enabled',Default=false});return {State=state}end,{Replace=true})
  local a=s:AddComponent('test-pair',{Id='one',Props={Default=3}});local b=s:AddComponent('test-pair',{Id='two',Props={Default=4}});a:SetValue({value=8,enabled=true});assert(a:Get('value').Id=='one/value' and b:GetValue().value==4 and a.State:Get().value==8);local st=a.Exports.State;a:Destroy();assert(st.Destroyed and not b.Destroyed and w.Controls['one/value']==nil);finish(w)
 end)
 test('a component builder failure cleans already-created controls and States',function()
  local w,s=fixture();local state;Library:RegisterComponent('bad-builder',function(ctx)ctx:Add('Toggle',{Id='child'});state=ctx:CreateState(1);error('intentional')end,{Replace=true});assert(not pcall(s.AddComponent,s,'bad-builder',{Id='bad'}));assert(w.Controls['bad/child']==nil and state.Destroyed and not w._componentGroups.bad);finish(w)
 end)
 test('component registries reject duplicate names and unknown components',function()
  local w,s=fixture();Library:RegisterComponent('unique-builder',function()end,{Replace=true});assert(not pcall(Library.RegisterComponent,Library,'unique-builder',function()end));assert(not pcall(s.AddComponent,s,'missing-builder',{Id='missing'}));finish(w)
 end)
 local function records(count)local r={};for i=1,count do r[i]={Id='item-'..i,Title='Item '..i,Description='Description '..i,Icon='diamond',Category=i%2==0 and 'even' or 'odd',Badges={'Demo'}}end;return r end
 test('card grids recycle a bounded pool for thousands of records',function()
  local w,s=fixture();Mock.Geometry=true;local c=s:AddCardGrid({Id='grid',Items=records(5000),Height=320});Mock.pump();local first=c:GetViewStats();assert(first.Total==5000 and first.Pool>0 and first.Pool<=64);c.Viewport.CanvasPosition=Vector2.new(0,8000);Mock.pump();assert(c:GetViewStats().Pool<=64);finish(w)
 end)
 test('grid filters and copies preserve selected IDs across reordered items',function()
  local w,s=fixture();local c=s:AddCardGrid({Id='grid',Items=records(20)});c:SetValue('item-4',true);local copy=c:GetItems();copy[1].Title='Changed';assert(c:GetItems()[1].Title=='Item 1');c:SetFilter('even');assert(c:GetViewStats().Filtered==10);local list=records(20);list[1],list[4]=list[4],list[1];c:SetItems(list);assert(c:GetSelectedItem().Id=='item-4');c:SetFilter(nil);c:SetQuery('Item 19');assert(c:GetViewStats().Filtered==1);finish(w)
 end)
 test('grid actions are explicit and recycled cards read their current item',function()
  local w,s=fixture();local id;local c=s:AddCardGrid({Id='grid',Items=records(30),Actions={{Id='use',Text='Use',Callback=function(item)id=item.Id end}}});assert(id==nil);c:SetQuery('Item 29');c._cards[1].Actions[1].Activated:Fire();Mock.pump();assert(id=='item-29');finish(w)
 end)
 test('invalid grid replacements retain the previous catalog',function()
  local w,s=fixture();local c=s:AddCardGrid({Id='grid',Items=records(2)});c:SetValue('item-2',true);assert(not pcall(c.SetItems,c,{{Id='same'},{Id='same'}}));assert(c:GetViewStats().Total==2 and c:GetValue()=='item-2');finish(w)
 end)
 test('grid icons tolerate themes toggles and deferred hierarchy destruction',function()
  local w,s=fixture();s:AddCardGrid({Id='grid',Items=records(10)});for _,name in ipairs(Library:GetDesignerCatalog().ThemeNames)do w:SetTheme(name);w:SetPixelIcons(false);w:SetPixelIcons(true)end;Mock.DeferDestroying=true;w.Gui:Destroy();Mock.pump(100);finish(w)
 end)
 local function edge(a,b,c,d)return {From=a,Out=b,To=c,Input=d}end
 local function labelGraph(id,source,target,text)return {Id=id,Nodes={{Id='value',Type='Value',Control=source},{Id='format',Type='Format',Text=text or '{value}'},{Id='target',Type='Binding',Control=target,Property='Text'}},Edges={edge('value','Value','format','Value'),edge('format','Value','target','Value')}}end
 test('flow click events preserve original button callbacks and call explicit developer actions',function()
  local w,s=fixture();local original,actions=0,0;local button=s:AddButton({Id='button',Callback=function()original=original+1 end});w:CreateFlowGraph({Id='click',Nodes={{Id='event',Type='Click',Control='button'},{Id='call',Type='Call',Action='run'}},Edges={edge('event','Then','call','Execute')}},{Actions={run=function(ctx)ctx:ThrowIfCancelled();actions=actions+1;return true end}});assert(original==0 and actions==0);assert(button:Press());Mock.pump();assert(original==1 and actions==1);finish(w)
 end)
 test('flow bindings observe silent values without executing user callbacks',function()
  local w,s=fixture();local calls=0;local source=s:AddSlider({Id='source',Min=0,Max=10,Default=2,Callback=function()calls=calls+1 end});local target=s:AddLabel({Id='result',Title=''});w:CreateFlowGraph(labelGraph('values','source','result'));assert(target:GetValue()=='2');source:SetValue(7,true);assert(target:GetValue()=='7' and calls==0);finish(w)
 end)
 test('flow branches compare values and update a target only on the chosen path',function()
  local w,s=fixture();s:AddButton({Id='button'});local source=s:AddSlider({Id='source',Min=0,Max=10,Default=2});local target=s:AddToggle({Id='target',Default=false})
  local g=w:CreateFlowGraph({Id='branch',Nodes={{Id='event',Type='Click',Control='button'},{Id='value',Type='Value',Control='source'},{Id='limit',Type='Constant',Value=5},{Id='compare',Type='Compare',Operator='>'},{Id='branch',Type='Branch'},{Id='true',Type='Constant',Value=true},{Id='set',Type='SetValue',Control='target'}},Edges={edge('event','Then','branch','Execute'),edge('value','Value','compare','A'),edge('limit','Value','compare','B'),edge('compare','Value','branch','Condition'),edge('branch','True','set','Execute'),edge('true','Value','set','Value')}})
  g:Trigger('event');Mock.pump();assert(not target:GetValue());source:SetValue(9,true);g:Trigger('event');Mock.pump();assert(target:GetValue());finish(w)
 end)
 test('flow change events do not run during silent profile imports',function()
  local w,s=fixture();local source=s:AddToggle({Id='source',Default=false});local count=0;w:CreateFlowGraph({Id='changes',Nodes={{Id='event',Type='Change',Control='source'},{Id='call',Type='Call',Action='changed'}},Edges={edge('event','Then','call','Execute')}},{Actions={changed=function()count=count+1 end}})
  local p=w:ExportConfig(true);p.Flags.source.Value=true;assert(w:ImportConfig(p,{Silent=true}));Mock.pump();assert(count==0 and source:GetValue());source:SetValue(false);Mock.pump();assert(count==1);finish(w)
 end)
 test('flow validation rejects graph cycles before allocating resources',function()
  local w=fixture();assert(not pcall(w.CreateFlowGraph,w,{Id='cycle',Nodes={{Id='a',Type='Notify',Text='A'},{Id='b',Type='Notify',Text='B'}},Edges={edge('a','Then','b','Execute'),edge('b','Then','a','Execute')}}));assert(not w._flows or next(w._flows)==nil);finish(w)
 end)
 test('flow validation rejects value feedback through binding targets',function()
  local w,s=fixture();local t=s:AddToggle({Id='toggle'});assert(not Library:ValidateFlowGraph({Id='feedback',Nodes={{Id='value',Type='Value',Control='toggle'},{Id='write',Type='Binding',Control='toggle',Property='Value'}},Edges={edge('value','Value','write','Value')}},{Controls={toggle=t}}));finish(w)
 end)
 test('flow validation rejects data types and execution-to-data connections',function()
  local w,s=fixture();local t=s:AddToggle({Id='toggle'});assert(not Library:ValidateFlowGraph({Nodes={{Id='value',Type='Constant',Value='text'},{Id='write',Type='Binding',Control='toggle',Property='Value'}},Edges={edge('value','Value','write','Value')}},{Controls={toggle=t}}))
  assert(not Library:ValidateFlowGraph({Nodes={{Id='event',Type='Click',Control='button'},{Id='write',Type='Binding',Control='toggle',Property='Value'}},Edges={edge('event','Then','write','Value')}},{Controls={toggle=t,button=s:AddButton({Id='button'})}}));finish(w)
 end)
 test('missing action handlers fail closed without creating a graph',function()
  local w,s=fixture();s:AddButton({Id='button'});assert(not pcall(w.CreateFlowGraph,w,{Nodes={{Id='event',Type='Click',Control='button'},{Id='call',Type='Call',Action='missing'}},Edges={edge('event','Then','call','Execute')}}));assert(not w._flows or next(w._flows)==nil);finish(w)
 end)
 test('destroying a graph cancels cooperative calls and prevents following nodes',function()
  local w,s=fixture();Mock.YieldingTasks=true;s:AddButton({Id='button'});local target=s:AddToggle({Id='target'});local g=w:CreateFlowGraph({Id='cancel-graph',Nodes={{Id='event',Type='Click',Control='button'},{Id='call',Type='Call',Action='wait'},{Id='true',Type='Constant',Value=true},{Id='set',Type='SetValue',Control='target'}},Edges={edge('event','Then','call','Execute'),edge('call','Then','set','Execute'),edge('true','Value','set','Value')}},{Actions={wait=function(ctx)task.wait(.5);ctx:ThrowIfCancelled()end}});g:Trigger('event');Mock.pump();g:Destroy();Mock.pump(.6);assert(not target:GetValue());finish(w)
 end)
 test('destroyed graph subscriptions are removed and its Id can be reused',function()
  local w,s=fixture();s:AddToggle({Id='toggle'});local definition={Id='same',Nodes={{Id='value',Type='Value',Control='toggle'}},Edges={}};local g=w:CreateFlowGraph(definition);g:Destroy();g:Destroy();assert(w:CreateFlowGraph(definition));finish(w)
 end)
 test('binding chains use dependency order and definitions are defensive copies',function()
  local w,s=fixture();local source=s:AddSlider({Id='source',Min=0,Max=100,Default=7});s:AddSlider({Id='middle',Min=0,Max=100,Default=0});local target=s:AddSlider({Id='target',Min=0,Max=100,Default=0});local g=w:CreateFlowGraph({Id='chain',Nodes={{Id='b2',Type='Binding',Control='target',Property='Value'},{Id='v2',Type='Value',Control='middle'},{Id='b1',Type='Binding',Control='middle',Property='Value'},{Id='v1',Type='Value',Control='source'}},Edges={edge('v1','Value','b1','Value'),edge('v2','Value','b2','Value')}})
  assert(target:GetValue()==7);source:SetValue(19,true);assert(target:GetValue()==19);local copy=g:GetDefinition();copy.Nodes={};assert(#g:GetDefinition().Nodes==4);g:Destroy();assert(g:GetDefinition()==nil);finish(w)
 end)
 test('localized flow formats refresh when the window language changes',function()
  local w,s=fixture({Translations={value={Source='Valor: {value}',Values={['en-US']='Value: {value}'}}}});s:AddSlider({Id='source',Min=0,Max=100,Default=8});local label=s:AddLabel({Id='result',Title=''});w:CreateFlowGraph(labelGraph('locale-flow','source','result','value'));assert(label:GetValue()=='Valor: 8');w:SetLocale('en-US');assert(label:GetValue()=='Value: 8');finish(w)
 end)
 test('catalog diagnosis inspects raw URLs without executing their contents',function()
  local w=fixture();_G.__diagnosticExecuted=false;loadstring=load;local hub=w:CreateScriptHub({Id='diagnosis',Games={{Id='game',Name='Game',Scripts={{Id='game-script',Title='Game script',SourceURL='https://pastefy.app/mock-game/raw',Callback=function()end}}}},UniversalScripts={{Id='universal',Name='Universal',URL='https://pastefy.app/mock-universal/raw'}}});local h=assert(hub:DiagnoseCatalog({ValidateSyntax=true,Fetch=function()return '_G.__diagnosticExecuted=true'end}));Mock.pump();assert(h:GetStatus().Status=='Completed' and not _G.__diagnosticExecuted);local report=hub:GetCatalogDiagnosis();assert(#report.Entries==2 and report.Entries[1].Syntax=='Compiled');_G.__diagnosticExecuted=nil;finish(w)
 end)
 test('catalog diagnosis distinguishes HTML HTTP errors and callbacks',function()
  local w=fixture();local hub=w:CreateScriptHub({Id='diagnosis',Games={},UniversalScripts={{Id='html',Name='HTML',URL='https://pastefy.app/mock-html/raw'},{Id='offline',Name='Offline',URL='https://pastefy.app/mock-offline/raw'},{Id='local',Name='Callback',Callback=function()error('must not run')end}}});hub:DiagnoseCatalog({Fetch=function(url)if url:find('html',1,true)then return '<html>login</html>'end;return {StatusCode=404,Body='not found'}end});Mock.pump();local rows=hub:GetCatalogDiagnosis().Entries;assert(rows[1].Status=='HTML' and rows[2].Status=='HTTPError' and rows[3].Status=='Callback');finish(w)
 end)
 test('diagnostic UI releases observers when the Hub and its parent are destroyed',function()
  local w=fixture();local hub=w:CreateScriptHub({Id='diagnosis',Games={},UniversalScripts={}});local tab=hub:OpenCatalogDiagnostics();assert(tab==hub:OpenCatalogDiagnostics());hub:Destroy();Mock.pump();assert(tab.Destroyed);finish(w)
 end)
end
